using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Pricing;

public sealed class LoyaltyTierPricingTests
{
    [Fact]
    // Returning Bronze customer is charged the Bronze price
    public void Bronze_customer_pricing_a_10000_cent_basket_is_charged_9500_cents()
    {
        var quote = new CalculateLoyaltyDiscount().Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }
}

